(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma sc_call_cem : acem_ctor_stmt H ->
  forall (s : as_St H) (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp tp : word)
         (saved gap : list cell) (h32 j472 shb : list byte) (errv : word) (cs1 cs2 lc : list cell) (jm : list byte) (m : mem) (en spin : Z)
         (rax gp t0 t1 t2 a3 a4 a5 a6 a7 xs2 xs3 xs5 xs6 xs7 xs9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (Q : machine_state -> Prop),
  sc_invt H s LB LF S ioc regb cfgb lo shi spa ff fp sp saved gap h32 j472 shb errv (cs1 ++ [CB 56 jm] ++ cs2) lc m ->
  Z.of_nat (cells_size cs1) = 56 ->
  sc_side H LB LF S ioc regb cfgb lo shi spa ff fp sp tp ->
  (en = 0 \/ en = 1) -> 0 <= spin < 2^31 -> bv_unsigned rax mod 2 = 0 ->
  (forall (m' : mem) (ff' fp' : Z) (j3 : list byte) (t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word),
     sc_invt H s LB LF S ioc regb cfgb lo shi spa ff fp sp saved gap h32 j472 shb errv
             (cs1 ++ ([CB 8 (firstn 8 jm)] ++ apmutex_cells 0 ++ [C4 (wz spin); CB 1 [b8 en]; CB 3 j3]) ++ cs2) lc m' ->
     fresh_frame H ((3, ff, fp) :: LF) 2 ff' fp' ->
     munch ([(lo, spa); (S + 56, S + 56 + 56)]%Z ++ fr2_XS H ff' fp') m m' -> wmono asegs m m' ->
     evt asegs Q (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
                           xs2 xs3 (Z_to_bv 64 S) xs5 xs6 xs7 (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3' t4' t5' t6')
                  F (ret_pc rax) fc None m' (seg_rom asegs))) ->
  evt asegs Q (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (wz (S + 56)) (wz en) (wz spin) a3 a4 a5 a6 a7
                        xs2 xs3 (Z_to_bv 64 S) xs5 xs6 xs7 (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
               F (Z_to_bv 64 P_A_CEM_CTOR) fc None m (seg_rom asegs)).
Proof.
  intros CEM. intros until Q. intros INV CSZ SIDE EN SPIN RA K.
  destruct INV as (LOC & LSZ & GAP & GSZ & SAVED & SSZ & FRM & SHU & FL & OBJ & OSZ & ADS & ST & MI & AINV & HP & RF & AC & SK).
  pose proof SIDE as (PURE & AFS & FF & INS & SPAC & LFN & DS1 & DS3).
  pose proof PURE as (RBS & KFSB & IPOS & I8 & API & DCR & DSR & DSC & DIS & DIR & TPV & SPAL & SPHI & LO & CEIL & _ & SHI).
  pose proof AFS as (FOS & FOI & FOR & FOC). pose proof AINV as (RI & ACI & REG & CFG & XS & CR & CN & ERR).
  pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
  pose proof aceil_facts as (AF1 & AF2 & AF3). pose proof (stack0_bounds _ _ _ SK) as [SKB1 SKB2].
  pose proof (rblock_bounds _ _ RBS) as (Q0 & QN & QHI & QIMG & QTOP & Q8). pose proof RBS as (QP & Q16 & _ & APS & _).
  assert (SPAR : bv_unsigned sp + -208 <= spa <= bv_unsigned sp + -192 /\ spa mod 16 = 0)
    by (clear - SPAC SPAL; destruct SPAC as [-> | ->]; split; try lia; Z.div_mod_to_equations; lia).
  destruct SPAR as (SPAR & SPA16).
  pose proof LO as LO'. unfold ASCHED_CTOR_STACK, ACONFIG_GET_STACK, AGET_VALUE_STACK, ASNPRINTF_STACK in LO'.
  pose proof (ah_thr H HH _ _ _ HP) as ATH.
  (* [comment removed for export] *)
  apply (proj1 (rw_cells_app _ _ _ cs1 _)) in OBJ. destruct OBJ as [OB1 OBJ]. rewrite CSZ in OBJ.
  apply (proj1 (rw_cells_app _ _ _ [_] _)) in OBJ. destruct OBJ as [OBM OB2]. cbn [cells_size csize Nat.add] in OB2.
  replace (S + 56 + Z.of_nat 56) with (S + 112) in OB2 by (clear; lia).
  pose proof CEM as CI. unfold acem_ctor_stmt in CI.
  eapply evt_cut.
  { eapply (CI (S + 56) en spin lo shi ((3, ff, fp) :: LF)) with (junk := jm); clear CI K.
